mapper.update:
update flights
set available_seats = #{flight.availableSeats},
    updated_at = #{flight.updatedAt}
where id = #{flight.id}

mapper.select:
select * from flights


        and origin = #{origin}


        and destination = #{destination}


order by departure_time asc
limit #{limit} offset #{offset}

select count(*) from flights


        and origin = #{origin}


        and destination = #{destination}
